wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Granted by the graph author ahead of the graph update: record the
        // input this call received under `last-input` in the shared store.
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is a value (Err), so it
        // yields fetched = 0 rather than failing the run. An out-of-allowlist
        // URL traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let notified = notifier::notify("digest");

        // The `ensures notified == true` contract: a refused notification must
        // not be reported as a success, so abort the run instead of returning
        // a report that violates the contract.
        if !notified {
            panic!("notifier refused the digest notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

